-- Schema produced by AutoMigrate before user_id columns were removed (multi-user era).
CREATE TABLE `audit_events` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer,`event_type` text,`action` text,`description` text,`entity_type` text,`entity_id` integer,`metadata` text,`ip_address` text,`user_agent` text,`status` text,`error_msg` text,`created_at` datetime);
CREATE TABLE `book_tags` (`tag_id` integer,`book_id` integer,PRIMARY KEY (`tag_id`,`book_id`),CONSTRAINT `fk_book_tags_tag` FOREIGN KEY (`tag_id`) REFERENCES `tags`(`id`),CONSTRAINT `fk_book_tags_book` FOREIGN KEY (`book_id`) REFERENCES `books`(`id`));
CREATE TABLE `books` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer,`title` text,`author` text,`isbn` text,`asin` text,`cover_url` text,`publisher` text,`publication_year` integer,`file_path` text,`file_hash` text,`external_id` text,`source_id` integer,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,CONSTRAINT `fk_books_source` FOREIGN KEY (`source_id`) REFERENCES `sources`(`id`),CONSTRAINT `fk_books_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `deleted_entities` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer,`entity_type` text,`entity_key` text,`source_id` integer,`deleted_at` datetime);
CREATE TABLE `highlight_tags` (`tag_id` integer,`highlight_id` integer,PRIMARY KEY (`tag_id`,`highlight_id`),CONSTRAINT `fk_highlight_tags_tag` FOREIGN KEY (`tag_id`) REFERENCES `tags`(`id`),CONSTRAINT `fk_highlight_tags_highlight` FOREIGN KEY (`highlight_id`) REFERENCES `highlights`(`id`));
CREATE TABLE `highlights` (`id` integer PRIMARY KEY AUTOINCREMENT,`book_id` integer,`user_id` integer,`text` text,`note` text,`location_type` text DEFAULT "page",`location_value` integer,`location_end` integer,`percent` real,`chapter` text,`color` text,`style` text DEFAULT "highlight",`highlighted_at` datetime,`is_favorite` numeric DEFAULT false,`is_discarded` numeric DEFAULT false,`context_prefix` text,`context_suffix` text,`external_id` text,`source_id` integer,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,CONSTRAINT `fk_highlights_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`),CONSTRAINT `fk_books_highlights` FOREIGN KEY (`book_id`) REFERENCES `books`(`id`),CONSTRAINT `fk_highlights_source` FOREIGN KEY (`source_id`) REFERENCES `sources`(`id`));
CREATE TABLE `import_sessions` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer,`source_id` integer,`status` text DEFAULT "pending",`books_processed` integer,`highlights_processed` integer,`books_created` integer,`highlights_created` integer,`errors` text,`started_at` datetime,`completed_at` datetime,CONSTRAINT `fk_import_sessions_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`),CONSTRAINT `fk_import_sessions_source` FOREIGN KEY (`source_id`) REFERENCES `sources`(`id`));
CREATE TABLE `settings` (`id` integer PRIMARY KEY AUTOINCREMENT,`key` text,`value` text,`created_at` datetime,`updated_at` datetime);
CREATE TABLE `sources` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text,`display_name` text,`created_at` datetime);
CREATE TABLE `sync_progress` (`id` integer PRIMARY KEY AUTOINCREMENT,`sync_type` text,`status` text,`total_items` integer,`processed` integer,`succeeded` integer,`failed` integer,`skipped` integer,`current_item` text,`error` text,`started_at` datetime,`updated_at` datetime,`completed_at` datetime);
CREATE TABLE `tags` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer,`name` text,`created_at` datetime,CONSTRAINT `fk_tags_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
CREATE TABLE `users` (`id` integer PRIMARY KEY AUTOINCREMENT,`username` text,`email` text,`password_hash` text,`role` text DEFAULT "viewer",`token` text,`token_hash` text,`token_created_at` datetime,`last_login_at` datetime,`created_at` datetime,`updated_at` datetime,`deleted_at` datetime,`failed_login_count` integer DEFAULT 0,`locked_until` datetime);
CREATE TABLE `word_definitions` (`id` integer PRIMARY KEY AUTOINCREMENT,`word_id` integer,`part_of_speech` text,`definition` text,`example` text,`pronunciation` text,`audio_url` text,`source` text,`created_at` datetime,CONSTRAINT `fk_words_definitions` FOREIGN KEY (`word_id`) REFERENCES `words`(`id`));
CREATE TABLE `words` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer,`word` text,`highlight_id` integer,`book_id` integer,`context` text,`status` text DEFAULT "pending",`source_book_title` text,`source_book_author` text,`source_highlight_text` text,`enrichment_error` text,`created_at` datetime,`updated_at` datetime,CONSTRAINT `fk_words_highlight` FOREIGN KEY (`highlight_id`) REFERENCES `highlights`(`id`) ON DELETE SET NULL,CONSTRAINT `fk_words_book` FOREIGN KEY (`book_id`) REFERENCES `books`(`id`) ON DELETE SET NULL,CONSTRAINT `fk_words_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`));
